    {
      "rank": 1,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Gavin E. Crooks"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations give deep, broadly applicable constraints on nonequilibrium systems and connect microscopic reversibility to measurable macroscopic work. Their conceptual reach and influence make this a strong prize-level contribution.",
        "attribution": "The credited theorists made distinct, complementary contributions: Evans to early fluctuation relations, Jarzynski to the nonequilibrium work equality, and Crooks to a related work theorem. Credit should track these separate results.",
        "maturity": "The relations have been tested and applied across a wide range of systems over decades; their theoretical foundations are well established.",
        "uncertainties": [
          "The precise division of credit among closely related early results needs care."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electron systems tractable through a powerful self-consistent framework, enabling quantitative insight into phenomena such as the Mott transition. It is a major and lasting theoretical advance.",
        "attribution": "Georges, Vollhardt, and Kotliar were central to formulating and establishing the modern framework. The theory arose through related early work, so a prize citation should distinguish foundational formulation from subsequent development.",
        "maturity": "The method has been developed, tested against experiments, and extended extensively since the 1990s.",
        "uncertainties": [
          "Metzner and other contributors to the early formulation are absent from the credited names, leaving attribution potentially incomplete."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and discovery of correlated phases in magic-angle twisted bilayer graphene opened a striking route to tune quantum matter through geometry. The combination of a simple theoretical mechanism and experimentally rich phases is highly compelling.",
        "attribution": "Bistritzer and MacDonald established the moiré-band theory that identified the special angle; Jarillo-Herrero's group observed the resulting correlated behavior. This theory–experiment pairing is a strong attribution case.",
        "maturity": "The platform has generated extensive follow-up work, but understanding of its phases and their mechanisms remains active.",
        "uncertainties": [
          "The nature and origin of superconductivity and other correlated phases remain unsettled.",
          "The durability of the field's broader impact is still being established."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed robust electronic phases classified by topology and reshaped condensed-matter physics. The prediction–realization arc is especially strong.",
        "attribution": "Kane and Mele developed the key theoretical proposals, while Molenkamp's experiments established the quantum spin Hall effect in a material system. The listed credit captures central theoretical and experimental steps.",
        "maturity": "Topological insulators are an established field with extensive experimental confirmation and durable conceptual influence.",
        "uncertainties": [
          "The broader list of influential experimental realizations and theoretical contributors makes a three-person attribution selective."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation gave experimental access to controlled many-body Hamiltonians and enabled landmark studies of quantum phases. It is a powerful general method linking theory to experiment.",
        "attribution": "Bloch and Greiner were central to the experimental realization and demonstrations; Zoller helped establish the theoretical framework for quantum simulation with trapped atoms. Juan Ignacio Cirac also made important theoretical contributions.",
        "maturity": "The platform is mature and has yielded reproducible phenomena and extensive follow-up work, although its scope as a quantitatively predictive simulator continues to develop.",
        "uncertainties": [
          "The contribution of theory and experiment is distributed across a wider community than the three selected names."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Claudio Castelnovo",
        "Roderich Moessner",
        "Shivaji L. Sondhi"
      ],
      "assessment": {
        "nobel_worthiness": "The identification of emergent magnetic monopole-like excitations in spin ice gave vivid physical meaning to fractionalized excitations and advanced understanding of frustrated magnetism.",
        "attribution": "Castelnovo, Moessner, and Sondhi jointly developed the influential monopole interpretation and its statistical-physics account.",
        "maturity": "The spin-ice phenomenology is established, with substantial experimental support for the predicted excitations.",
        "uncertainties": [
          "These are emergent quasiparticles in a material, not isolated fundamental magnetic monopoles; the distinction should remain clear in the prize framing."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a versatile platform for strong light–matter coupling and control of superconducting qubits. Its impact on quantum information and quantum optics is substantial.",
        "attribution": "Blais supplied key theoretical proposals, while Wallraff and Schoelkopf led landmark experimental demonstrations and development of the platform.",
        "maturity": "The framework and experimental methods are mature, with a large body of reproducible work and continuing technical progress.",
        "uncertainties": [
          "The platform's long-term practical and scientific reach is still evolving."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exceptional precision with a conceptually important advance in atomic measurement, enabling new tests of fundamental physics and applications in geodesy and timekeeping.",
        "attribution": "Katori and Ye made complementary, pioneering contributions to the optical-lattice clock approach and its experimental realization.",
        "maturity": "The clocks have reached remarkable accuracy and stability, with independent implementations and expanding scientific use.",
        "uncertainties": [
          "The prize case depends on treating the clock as a fundamental physics advance rather than chiefly an enabling precision technology."
        ]
      }
    }
  ]
